definition.script:
pipeline {
    agent none
    stages {
        stage('Ask') {
            steps {
                script {
                    def target = input(
                        id: 'Release',
                        message: 'Ship it?',
                        ok: 'Ship it',
                        parameters: [string(name: 'TARGET', defaultValue: 'eu')]
                    )
                    echo "target=${target}"
                }
            }
        }
    }
}
